            check(collect_from_ini(0xFFFF)==kTopicAll && collect_from_ini(0)==0 && collect_to_ini(kTopicAll)==0x6FFFFFFFu && collect_from_ini(collect_to_ini(0x2A5A5A5u&kTopicAll))==(0x2A5A5A5u&kTopicAll) && collect_from_ini(collect_to_ini(0))==0,"collect value: old 16-bit values, the new marked value and its round trip");
