            check(!(collect2_from_ini(0,kTopicAll&~topic_bit(Topic::City))&bit2(Topic::Shortage)) && !(collect2_from_ini(0,kTopicAll&~topic_bit(Topic::Rise))&(bit2(Topic::Coalition)|bit2(Topic::Emperor))) &&
                  !(collect2_from_ini(0,kTopicAll&~topic_bit(Topic::Diplomacy))&bit2(Topic::AttackRequest)) && !(collect2_from_ini(0,kTopicAll&~topic_bit(Topic::Weather))&bit2(Topic::Omen)),"parents: 도시 -> 봉록, 세력 흥망 -> 연합·황제, 외교 -> 공격요청, 천시 -> 징조");
            const LONG saved_mask2=collect_mask2;collect_mask=static_cast<LONG>(kTopicAll);collect_mask2=static_cast<LONG>(kTopicAll2);
            const std::vector<Topic> rows=settable_topics();
