            check(!collects(Topic::Proposal) && collects(Topic::Omen) && collects(Topic::Gold) && collect_mask==static_cast<LONG>(kTopicAll) && ends_with(collect_labels()[proposal_row],L"원작대로"),"a new topic's row flips collect2 only");
            collect_toggle(proposal_row);check(collect_mask2==static_cast<LONG>(kTopicAll2),"toggling it twice restores collect2");
